<template><div v-if="open" class="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/50 p-4"><div class="w-full max-w-2xl border bg-white"><div class="flex justify-between border-b p-6"><h2 class="text-lg font-semibold">New payment plan</h2><button @click="close" class="border px-3">×</button></div><form @submit.prevent="submit"><div class="grid gap-4 p-6 md:grid-cols-2"><Field label="Payment type"><select v-model="form.payment_type" class="input"><option>down_payment</option><option>installment</option><option>final_payment</option><option>other</option></select></Field><Field label="Frequency"><select v-model="form.frequency" class="input"><option>monthly</option><option>weekly</option><option>quarterly</option><option>yearly</option><option>one_time</option></select></Field><Field label="Amount"><input v-model="form.amount" class="input"/></Field><Field label="Due date"><input v-model="form.due_date" type="date" class="input"/></Field><Field label="Installment number"><input v-model.number="form.installment_number" type="number" min="1" class="input"/></Field><Field label="Total installments"><input v-model.number="form.total_installments" type="number" min="1" class="input"/></Field><Field label="Application ID"><input v-model.number="form.application" type="number" min="1" class="input"/></Field><Field label="Completed"><input v-model="form.is_completed" type="checkbox" class="h-4 w-4"/></Field><Field label="Description"><textarea v-model="form.description" class="input min-h-24"></textarea></Field></div><div v-if="error" class="mx-6 mb-4 border border-red-200 bg-red-50 p-3 text-red-700">{{error}}</div><div class="flex justify-end gap-3 border-t p-4"><button type="button" @click="close" class="border px-5 py-2.5">Cancel</button><button :disabled="loading" class="bg-primary px-5 py-2.5 text-white">{{loading?'Saving…':'Create plan'}}</button></div></form></div></div></template><script>import OffplanField from "../offplan property/OffplanField.vue";const blank=()=>({payment_type:"down_payment",frequency:"monthly",amount:"",due_date:"",installment_number:0,total_installments:0,description:"",is_completed:true,application:0});export default{name:"AddOffplanPaymentPlan",components:{Field:OffplanField},props:{open:Boolean},data(){return{form:blank(),loading:false,error:""}},watch:{open(v){if(v)this.form=blank()}},methods:{close(){if(!this.loading)this.$emit("close")},async submit(){this.loading=true;try{await this.$apiPost("/post_offplan_payment_plan",{...this.form,installment_number:Number(this.form.installment_number),total_installments:Number(this.form.total_installments),application:Number(this.form.application)});this.$emit("saved");this.close()}catch(e){this.error=e?.message||"Unable to create payment plan."}finally{this.loading=false}}}};</script><style scoped>.input{width:100%;border:1px solid #cbd5e1;padding:.625rem .75rem;outline:none}</style>